// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, string memory description) public {
        vm.assume(caller != address(0));
        // Ensure caller is not an admin initially
        vm.assume(!c.isAdmin(caller));

        // As a non-admin, try to call newEmergencyOracle
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("newEmergencyOracle(string)", description));

        // The call should always revert because caller is not admin
        assertTrue(!success);
    }
}

